mapper.select:
select a.FINPROD_ID finprodId, a.FINPROD_TYPE2 finprodType2, a.FINPROD_MARKET_ID finprodMarketId, a.FINPROD_NAME finprodName, a.FINPROD_ABBR finprodAbbr, a.CALENDAR_ID calendarId, a.IDATE idate, a.CCY ccy, a.VDATE vdate, a.MDATE mdate, a.TRADE_MARKET tradeMarket, b.TYPE_6 fundType, b.TYPE_7 secondType, /**added by wangguiqi on 2019/7/22 -start**/ b.TYPE_9 type9, b.TYPE_10 type10, b.TYPE_11 type11, b.TYPE_12 type12, /**added by wangguiqi on 2019/7/22 -end**/ c.IS_COMPOUND_INT isCompoundInt, d.CUSTOMER_NAME manager, f.PAY_TYPE divideMethod, f.PAY_CYCLE carryoverFreq,
(CASE WHEN C.PUR_SPEED is not null THEN 'T+'||C.PUR_SPEED ELSE '' END) purSpeed, (CASE WHEN C.RED_SPEED is not null THEN 'T+'||C.RED_SPEED ELSE '' END) redSpeed, c.TRM_FUND_TYPE trmFundType, c.TRM_FUND_ABBR trmFundAbbr from FIN_PRODUCT a left join MST_CUSTOMER_INFO d on d.CUSTOMER_ID = a.MANAGER left join FIN_CASH_INFO e on a.FINPROD_ID = e.FINPROD_ID and e.CASH_TYPE_2 = #{CASH_TYPE_2,jdbcType=VARCHAR} and e.FINPROD_TYPE = #{FIN_CASH_BUSINESS_TYPE,jdbcType=VARCHAR} left join FIN_CASH_PAY_RULE f on e.CASH_ID = f.CASH_ID and a.VDATE = f.EFF_DATE , FIN_PRODUCT_TYPE b , FIN_PRODUCT_ADD c where 1=1 and a.FINPROD_ID = b.FINPROD_ID and a.FINPROD_ID = c.FINPROD_ID and a.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F06,jdbcType=VARCHAR}
and a.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
and a.FINPROD_MARKET_ID LIKE CONCAT('%',CONCAT(#{finprodMarketId,jdbcType=VARCHAR},'%'))
and a.CCY = #{ccy,jdbcType=VARCHAR}
and a.VDATE between #{sDate} and #{eDate}
and a.TRADE_MARKET = #{tradeMarket,jdbcType=VARCHAR}
and a.MANAGER = #{manager,jdbcType=VARCHAR}
and b.TYPE_6 = #{fundType,jdbcType=VARCHAR}
AND b.TYPE_9 in
#{item}
AND b.TYPE_10 in
#{item}
AND b.TYPE_11 in
#{item}
and f.PAY_TYPE = #{divideMethod,jdbcType=VARCHAR}
and f.PAY_CYCLE = #{carryoverFreq,jdbcType=VARCHAR}
AND c.PUR_SPEED like concat(concat('%',#{purSpeed,jdbcType=VARCHAR}),'%')
AND c.RED_SPEED like concat(concat('%',#{redSpeed,jdbcType=VARCHAR}),'%')
AND c.TRM_FUND_TYPE in
#{item}

select a.FINPROD_ID finprodId, a.FINPROD_MARKET_ID finprodMarketId, a.FINPROD_NAME finprodName, a.FINPROD_ABBR finprodAbbr, a.FINPROD_TYPE2 finprodType2, a.CALENDAR_ID calendarId, a.IDATE idate, a.CCY ccy, a.VDATE vdate, a.MDATE mdate, a.TRADE_MARKET tradeMarket, a.MANAGER manager, b.TYPE_6 fundType, b.TYPE_7 secondType, /**added by wangguiqi on 2019/7/22 -start**/ b.TYPE_9 type9, b.TYPE_10 type10, b.TYPE_11 type11, b.TYPE_12 type12,
T9.POST_ORG postOrg,
/**added by wangguiqi on 2019/7/22 -end**/ c.IS_COMPOUND_INT isCompoundInt, d.CUSTOMER_ID manager, f.PAY_TYPE divideMethod, f.PAY_CYCLE carryoverFreq, a.REMARK remark,
c.PUR_SPEED, c.RED_SPEED, T.PFLSH pflsh, T.HAP_CREDIT_AMT hapCreditAmt, T.CREDIT_FLAG creditFlag, g.ACTUAL_CREDIT_PROVID actualCreditProvid, a.CAPI_INCOME_FEATURE capiIncomeFeature, c.INVEST_NATURE investNature, a.CONTRACT_NO, g.TRIAL_NO,
c.TOFF_STRDATE, c.TOFF_ENDDATE, c.TRM_FUND_ABBR, c.TRM_FUND_TYPE, c.GRA_FUND_TYPE, c.PUR_RED_ID, c.PUR_RED_ABBR, c.PUR_START_LOW, c.RED_START_LOW, c.ETF_TYPE, c.ETF_MIN_PRUNIT, c.FUND_MANGER_NAME fundMangerName, c.IS_SEVEN_DAY_CASHABLE isSevenDayCashable, c.OPEN_TYPE openType, a.P_FINPROD_ID, aa.FINPROD_MARKET_ID pMarketId
from FIN_PRODUCT a LEFT JOIN (SELECT T2.FINPROD_ID,T1.CREDIT_FLAG,T1.PFLSH,T1.HAP_CREDIT_AMT ,T1.CUSTOMER_ID FROM CREDIT_LINES T1 LEFT JOIN CREDIT_ASSETPOOL_DETAIL T2 ON T1.CUSTOMER_ID = T2.SEQNO) T ON (T.FINPROD_ID = a.FINPROD_ID OR T.CUSTOMER_ID = a.FINPROD_ID) left join MST_CUSTOMER_INFO d on d.CUSTOMER_ID = a.ISSUER left join FIN_CASH_INFO e on a.FINPROD_ID = e.FINPROD_ID and e.CASH_TYPE_2 = #{CASH_TYPE_2,jdbcType=VARCHAR} and e.FINPROD_TYPE = #{FIN_CASH_BUSINESS_TYPE,jdbcType=VARCHAR}
left join FIN_POST_INVEST_INFO T9 on T9.FINPROD_ID=a.FINPROD_ID
left join FIN_CASH_PAY_RULE f on e.CASH_ID = f.CASH_ID and a.VDATE = f.EFF_DATE LEFT JOIN PA_FIN_PRODUCT g ON a.FINPROD_ID = g.FINPROD_ID LEFT JOIN FIN_PRODUCT aa ON aa.FINPROD_ID = a.P_FINPROD_ID, FIN_PRODUCT_TYPE b , FIN_PRODUCT_ADD c where a.FINPROD_ID = b.FINPROD_ID and a.FINPROD_ID = c.FINPROD_ID and a.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F06,jdbcType=VARCHAR}
and a.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
